import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import Webcam from "react-webcam";

function JoinExam() {
  const [exams, setExams] = useState([]);
  const [selectedExam, setSelectedExam] = useState(null);
  const [verificationResult, setVerificationResult] = useState(null);
  const [verified, setVerified] = useState(false);
  const [running, setRunning] = useState(false);
  const [loading, setLoading] = useState(false);

  const webcamRef = useRef(null);
  const token = localStorage.getItem("token");

  // 📚 Prüfungen laden
  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/api/students/exams/", {
        headers: { Authorization: `Token ${token}` },
      })
      .then((res) => setExams(res.data))
      .catch((err) => console.error("Fehler beim Laden der Prüfungen:", err));
  }, [token]);

  // 📷 Alle 2 Sekunden einen Frame zur Identitätsprüfung senden
  useEffect(() => {
    if (!running || !selectedExam) return;
    const interval = setInterval(async () => {
      const imageSrc = webcamRef.current?.getScreenshot();
      if (!imageSrc) return;

      const blob = await (await fetch(imageSrc)).blob();
      const form = new FormData();
      form.append("frame", blob, "frame.jpg");

      try {
        const res = await axios.post(
          "http://127.0.0.1:8000/api/students/live-verify/",
          form,
          {
            headers: {
              Authorization: `Token ${token}`,
              "Content-Type": "multipart/form-data",
            },
          }
        );

        setVerificationResult(res.data);

        if (res.data.verified) {
          setVerified(true);
          setRunning(false);
          joinExam(selectedExam.id);
        }
      } catch (err) {
        console.error("Fehler bei Live-Verification:", err);
      }
    }, 2000);

    return () => clearInterval(interval);
  }, [running, selectedExam, token]);

  // 🧑‍🎓 Student tritt der Prüfung bei
  const joinExam = async (examId) => {
    setLoading(true);
    try {
      const res = await axios.post(
        `http://127.0.0.1:8000/api/students/exams/${examId}/join/`,
        {},
        { headers: { Authorization: `Token ${token}` } }
      );
      alert(res.data.message || "Erfolgreich der Prüfung beigetreten!");
      setVerified(false);
      setSelectedExam(null);
    } catch (err) {
      console.error(err);
      alert("Fehler beim Beitritt zur Prüfung.");
    } finally {
      setLoading(false);
    }
  };

  // 🧩 Rendering
  return (
    <div style={{ padding: "20px" }}>
      <h2>📋 Prüfungen</h2>

      {/* Prüfungsübersicht */}
      <ul>
        {exams.map((exam) => (
          <li key={exam.id} style={{ marginBottom: 10 }}>
            {exam.title} – {exam.date}
            <button
              style={{ marginLeft: 10 }}
              onClick={() => {
                setSelectedExam(exam);
                setVerified(false);
                setVerificationResult(null);
                setRunning(false);
              }}
            >
              Beitreten
            </button>
          </li>
        ))}
      </ul>

      {/* Identitätsprüfung */}
      {selectedExam && (
        <div style={{ marginTop: 30 }}>
          <h3>🧾 Live-Identitätsprüfung für {selectedExam.title}</h3>
          <p>
            Halte dein <strong>Gesicht</strong> deutlich sichtbar in die Kamera
            und halte gleichzeitig deinen{" "}
            <strong>Studentenausweis</strong> so, dass Foto und Daten gut lesbar
            sind. Die Verifikation läuft automatisch.
          </p>

          {/* Kameraanzeige */}
          <div style={{ position: "relative", display: "inline-block" }}>
            <Webcam
              ref={webcamRef}
              audio={false}
              screenshotFormat="image/jpeg"
              width={480}
              height={360}
              videoConstraints={{ facingMode: "user" }}
            />
          </div>

          {/* Steuerung */}
          <div style={{ marginTop: 20 }}>
            {!running ? (
              <button onClick={() => setRunning(true)}>
                Live-Überprüfung starten
              </button>
            ) : (
              <button onClick={() => setRunning(false)}>
                Überprüfung stoppen
              </button>
            )}
          </div>

          {/* Ergebnisanzeige */}
          {verificationResult && (
            <div
              style={{
                marginTop: 20,
                padding: 12,
                borderRadius: 8,
                background: "#f8fafc",
                border: "1px solid #e5e7eb",
              }}
            >
              {/* Statusanzeige */}
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                <StatusPill
                  label="Gesicht"
                  active={verificationResult.face_detected}
                />
                <StatusPill
                  label="Ausweisfoto"
                  active={verificationResult.id_face_detected}
                />
                <StatusPill
                  label="Match"
                  active={verificationResult.faces_verified}
                />
                <StatusPill
                  label="DB"
                  active={
                    verificationResult?.db_compare?.name_match ||
                    verificationResult?.db_compare?.matriculation_match
                  }
                />
              </div>

              {/* Hinweise */}
              <div style={{ marginTop: 10 }}>
                {verificationResult.hints?.length > 0 ? (
                  <ul
                    style={{
                      margin: 0,
                      paddingLeft: 18,
                      color: "#111827",
                      lineHeight: 1.4,
                    }}
                  >
                    {verificationResult.hints.map((hint, i) => (
                      <li key={i}>💡 {hint}</li>
                    ))}
                  </ul>
                ) : (
                  <p style={{ color: "#6b7280", margin: 0 }}>
                    Warte auf stabile Erkennung …
                  </p>
                )}
              </div>
            </div>
          )}

          {verified && (
            <p
              style={{
                color: "green",
                fontWeight: "bold",
                marginTop: 20,
              }}
            >
              ✅ Identität bestätigt – du wirst zur Prüfung hinzugefügt …
            </p>
          )}

          {loading && <p>⏳ Wird verarbeitet …</p>}
        </div>
      )}
    </div>
  );
}

/* Kleine Komponente für die farbigen Status-Anzeigen */
const StatusPill = ({ label, active }) => (
  <span
    style={{
      padding: "4px 10px",
      borderRadius: 999,
      background: active ? "#dcfce7" : "#fee2e2",
      border: "1px solid #d1d5db",
      fontSize: 13,
    }}
  >
    {label}: {active ? "✅" : "❌"}
  </span>
);

export default JoinExam;
